import{_ as l,c as i,o as a,a3 as r}from"./chunks/framework.MI-M1z4O.js";const h=JSON.parse('{"title":"ミーティングチェックリストおよび進行手順","description":"スクラムバン（Scrumban）は、スクラムの反復的な構造とカンバンのフロー管理・WIP制限を組み合わせ、柔軟かつ効率的に作業を管理するハイブリッドアジャイル手法です。","frontmatter":{"title":"ミーティングチェックリストおよび進行手順","description":"スクラムバン（Scrumban）は、スクラムの反復的な構造とカンバンのフロー管理・WIP制限を組み合わせ、柔軟かつ効率的に作業を管理するハイブリッドアジャイル手法です。","head":[["meta",{"name":"keywords","content":"ミーティングチェックリストおよび進行手順, Scrumban, スクラムバン紹介, スクラムバン概念, スクラムバンとは, Scrumban紹介, Scrumban概念, スクラムとカンバンの違い, スクラム vs カンバン, アジャイル手法, アジャイルフレームワーク, カンバン手法, スクラム手法, スクラムバンプロセス, スクラムバン運用ガイド, スクラムバンボード, WIP制限, 作業フロー管理, カンバンボードの使い方, スクラムバンのメリット, スクラムバンの特徴, スクラムバンの効果, スクラムバン活用事例, スクラムバン導入効果, スクラムバンJira設定, スクラムバンボードテンプレート, Scrumbanツール, スクラムバンコラボレーションツール, スクラムバンワークフロー, アジャイルプロジェクト管理, 業務効率化手法, 反復作業管理, ボトルネック解消"}],["meta",{"property":"og:title","content":"ミーティングチェックリストおよび進行手順"}],["meta",{"property":"og:description","content":"ミーティングチェックリストおよび進行手順：スクラムバン（Scrumban）は、スクラムの反復的な構造とカンバンのフロー管理・WIP制限を組み合わせ、柔軟かつ効率的に作業を管理するハイブリッドアジャイル手法です。"}],["meta",{"property":"og:image","content":"https://doc.empasy.com/images/favicon.png"}],["meta",{"property":"og:url","content":"https://doc.empasy.com/ja/agile/checklistAndProcedure"}],["link",{"rel":"canonical","href":"https://doc.empasy.com/ja/agile/checklistAndProcedure"}],["link",{"rel":"alternate","hreflang":"ko","href":"https://doc.empasy.com/agile/checklistAndProcedure"}],["link",{"rel":"alternate","hreflang":"en","href":"https://doc.empasy.com/en/agile/checklistAndProcedure"}],["link",{"rel":"alternate","hreflang":"ja","href":"https://doc.empasy.com/ja/agile/checklistAndProcedure"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://doc.empasy.com/agile/checklistAndProcedure"}]],"sort":450},"headers":[],"relativePath":"ja/agile/checklistAndProcedure.md","filePath":"ja/agile/checklistAndProcedure.md","lastUpdated":1795293539000}'),t={name:"ja/agile/checklistAndProcedure.md"};function n(o,e,s,c,p,d){return a(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="scrumban-ミーティング・イベント一覧と進行方法の詳細ガイド" tabindex="-1">Scrumban ミーティング・イベント一覧と進行方法の詳細ガイド <a class="header-anchor" href="#scrumban-ミーティング・イベント一覧と進行方法の詳細ガイド" aria-label="Permalink to “Scrumban ミーティング・イベント一覧と進行方法の詳細ガイド”">​</a></h1><h2 id="_1-デイリースタンドアップミーティング-daily-stand-up" tabindex="-1">1. <strong>デイリースタンドアップミーティング (Daily Stand-up)</strong> <a class="header-anchor" href="#_1-デイリースタンドアップミーティング-daily-stand-up" aria-label="Permalink to “1. デイリースタンドアップミーティング (Daily Stand-up)”">​</a></h2><ul><li><p><strong>目的</strong>: チームメンバーが現在の作業状況を共有し、障害要素を特定して、当日の目標を明確にするため。</p></li><li><p><strong>進行方法</strong>:</p><ul><li><p>毎日決まった時間（通常は午前中）に15分以内で実施します。</p></li><li><p>チームメンバー全員が立った状態で進行し、会議時間を短く保ちます。</p></li><li><p>各メンバーが次の3つの質問について簡潔に共有します：</p><ul><li>昨日何を実施したか？</li><li>今日何を実施する予定か？</li><li>現在の作業に障害要素はあるか？</li></ul></li><li><p>カンバンボードの前で実施し、作業の進行状況を視覚的に確認します。</p></li></ul></li></ul><h2 id="_2-バックログリファインメント-backlog-refinement" tabindex="-1">2. <strong>バックログリファインメント (Backlog Refinement)</strong> <a class="header-anchor" href="#_2-バックログリファインメント-backlog-refinement" aria-label="Permalink to “2. バックログリファインメント (Backlog Refinement)”">​</a></h2><ul><li><p><strong>目的</strong>: バックログアイテムを継続的にレビューし、優先順位の調整と作業単位への分解を行うプロセス。</p></li><li><p><strong>進行方法</strong>:</p><ul><li>定期的に（例：週1~2回）実施します。</li><li>PO（Product Owner）または関係担当者が参加し、ストーリーの優先順位を調整します。</li><li>チームとともにアイテムを分析し、必要に応じて業務をさらに小さな単位へ分割します。</li><li>作業に対する理解度と準備状態を高め、後続作業に支障が出ないように備えます。</li></ul></li></ul><h2 id="_3-リリースプランニング-release-planning" tabindex="-1">3. <strong>リリースプランニング (Release Planning)</strong> <a class="header-anchor" href="#_3-リリースプランニング-release-planning" aria-label="Permalink to “3. リリースプランニング (Release Planning)”">​</a></h2><ul><li><p><strong>目的</strong>: 中長期の目標設定と機能リリース計画の策定。</p></li><li><p><strong>進行方法</strong>:</p><ul><li>必要時または定期的に（例：毎月、四半期ごと）実施します。</li><li>チーム全体が参加し、目標機能とリリーススケジュールを協議します。</li><li>カンバンボードとスクラムのスプリント概念を適切に組み合わせて計画を立てます。</li><li>作業量（Work In Progress、WIP）制限を考慮し、現実的なスケジュールを策定します。</li></ul></li></ul><h2 id="_4-レビューミーティング-review-meeting" tabindex="-1">4. <strong>レビューミーティング (Review Meeting)</strong> <a class="header-anchor" href="#_4-レビューミーティング-review-meeting" aria-label="Permalink to “4. レビューミーティング (Review Meeting)”">​</a></h2><ul><li><p><strong>目的</strong>: 完了した作業の成果物を共有し、フィードバックを得る場。</p></li><li><p><strong>進行方法</strong>:</p><ul><li>定期的または必要に応じて実施します。</li><li>チームメンバーが完了した作業をデモンストレーション、または結果を共有します。</li><li>ステークホルダーおよびPOが出席し、フィードバックを提供します。</li><li>改善点と成功事例をチーム全体で議論します。</li></ul></li></ul><h2 id="_5-レトロスペクティブミーティング-retrospective" tabindex="-1">5. <strong>レトロスペクティブミーティング (Retrospective)</strong> <a class="header-anchor" href="#_5-レトロスペクティブミーティング-retrospective" aria-label="Permalink to “5. レトロスペクティブミーティング (Retrospective)”">​</a></h2><ul><li><p><strong>目的</strong>: チームの作業プロセスとコラボレーション手法を振り返り、改善点を導出するため。</p></li><li><p><strong>進行方法</strong>:</p><ul><li><p>定期的に実施します（例：2週間に1回、または月1回）。</p></li><li><p>チームメンバー全員が参加します。</p></li><li><p>一般的な進行手順：</p><ul><li>良かった点の共有</li><li>問題点と障害要素の洗い出し</li><li>改善アイデアの議論</li><li>実行可能なアクションアイテムの選定</li></ul></li><li><p>選定されたアクションアイテムは次回以降の期間に反映して実行します。</p></li></ul></li></ul><h2 id="_6-優先順位調整およびwip制限管理ミーティング" tabindex="-1">6. <strong>優先順位調整およびWIP制限管理ミーティング</strong> <a class="header-anchor" href="#_6-優先順位調整およびwip制限管理ミーティング" aria-label="Permalink to “6. 優先順位調整およびWIP制限管理ミーティング”">​</a></h2><ul><li><p><strong>目的</strong>: カンバンの要であるWIP制限を点検し、優先順位を調整して作業フローを最適化するため。</p></li><li><p><strong>進行方法</strong>:</p><ul><li>必要に応じて随時実施可能です。</li><li>チームが現在WIP上限を超過していないか確認します。</li><li>ボトルネックや遅延状況を把握し、解決策を協議します。</li><li>新規作業の追加時に優先順位を再調整します。</li></ul></li></ul><hr><h1 id="追加参考" tabindex="-1">追加参考 <a class="header-anchor" href="#追加参考" aria-label="Permalink to “追加参考”">​</a></h1><ul><li><strong>カンバンボードの活用</strong>: すべてのミーティングはカンバンボード（物理ボードまたはデジタルボード）を中心に行い、作業の可視化を徹底します。</li><li><strong>柔軟な進行</strong>: Scrumbanには厳格なスプリント期間がなく、必要に応じてミーティングの頻度や内容を調整できます。</li><li><strong>WIP制限の重要性</strong>: WIP制限を適切に守ることが、作業効率の向上とボトルネックの最小化において重要です。</li></ul><hr>',17)])])}const u=l(t,[["render",n]]);export{h as __pageData,u as default};
